/// The built-in PBR material (`fynkel.pbr@1`): factors multiply the matching textures; an unbound texture behaves as white (normal: flat).
///
/// `fynkel.PbrMaterial` (record, id 0, 184 bytes).
class PbrMaterial implements WireRecord {
