    writeOptionalAssetRef(d, offset + 112, metallicRoughnessTexture, strings);
    writeOptionalAssetRef(d, offset + 136, occlusionTexture, strings);
    writeOptionalAssetRef(d, offset + 160, emissiveTexture, strings);
  }

  /// Reads [wireSize] bytes at [offset]; [tail] resolves strings.
  static PbrMaterial decode(ByteData d, int offset, Uint8List tail) {
    return PbrMaterial(
      baseColor: readVec4(d, offset + 0),
      metallic: d.getFloat32(offset + 16, Endian.little),
      roughness: d.getFloat32(offset + 20, Endian.little),
      emissive: readVec3(d, offset + 24),
      emissiveStrength: d.getFloat32(offset + 36, Endian.little),
      normalScale: d.getFloat32(offset + 40, Endian.little),
      occlusionStrength: d.getFloat32(offset + 44, Endian.little),
