/// `fynkel.rec.InputAction` (record, id 0, 32 bytes).
class InputActionRecord implements WireRecord {
  const InputActionRecord({
    required this.name,
    required this.kind,
    required this.held,
    required this.pressed,
    required this.released,
    required this.framePressed,
    required this.frameReleased,
    required this.x,
    required this.y,
  });

  final String name;
  final int kind;
  final bool held;
  final bool pressed;
  final bool released;
  final bool framePressed;
  final bool frameReleased;
  /// `axis1d` value, `axis2d` x, a button 1/0.
  final double x;
  final double y;

  static const String schemaName = 'fynkel.rec.InputAction';
  static const int wireSize = 32;

  /// Writes [wireSize] bytes at [offset]; strings go to [strings].
  @override
  void encode(ByteData d, int offset, WireStrings strings) {
    writeWireString(d, offset + 0, name, strings);
    d.setUint32(offset + 8, kind, Endian.little);
    d.setUint8(offset + 12, held ? 1 : 0);
    d.setUint8(offset + 13, pressed ? 1 : 0);
    d.setUint8(offset + 14, released ? 1 : 0);
    d.setUint8(offset + 15, framePressed ? 1 : 0);
    d.setUint8(offset + 16, frameReleased ? 1 : 0);
    d.setFloat32(offset + 20, x, Endian.little);
    d.setFloat32(offset + 24, y, Endian.little);
  }

  /// Reads [wireSize] bytes at [offset]; [tail] resolves strings.
  static InputActionRecord decode(ByteData d, int offset, Uint8List tail) {
    return InputActionRecord(
      name: readWireString(d, offset + 0, tail),
      kind: d.getUint32(offset + 8, Endian.little),
      held: d.getUint8(offset + 12) != 0,
      pressed: d.getUint8(offset + 13) != 0,
      released: d.getUint8(offset + 14) != 0,
      framePressed: d.getUint8(offset + 15) != 0,
      frameReleased: d.getUint8(offset + 16) != 0,
      x: d.getFloat32(offset + 20, Endian.little),
      y: d.getFloat32(offset + 24, Endian.little),
    );
  }

  @override
  bool operator ==(Object other) =>
      other is InputActionRecord && other.name == name && other.kind == kind && other.held == held && other.pressed == pressed && other.released == released && other.framePressed == framePressed && other.frameReleased == frameReleased && other.x == x && other.y == y;

  @override
  int get hashCode => Object.hashAll([name, kind, held, pressed, released, framePressed, frameReleased, x, y]);

  @override
  String toString() => 'InputActionRecord(name: $name, kind: $kind, held: $held, pressed: $pressed, released: $released, framePressed: $framePressed, frameReleased: $frameReleased, x: $x, y: $y)';
}

