    required this.gravityScale,
    required this.ccd,
  });

  final BodyType bodyType;
  /// Kilograms (dynamic only, `> 0`); the inertia follows the collider shape scaled to this mass.
  final double mass;
  /// Per-second velocity decay, `>= 0`.
  final double linearDamping;
  /// Per-second angular velocity decay, `>= 0`.
  final double angularDamping;
  /// Multiplies the world's gravity for this body (0 floats).
