    d.setUint32(offset + 0, bodyType.index, Endian.little);
    d.setFloat32(offset + 4, mass, Endian.little);
    d.setFloat32(offset + 8, linearDamping, Endian.little);
    d.setFloat32(offset + 12, angularDamping, Endian.little);
    d.setFloat32(offset + 16, gravityScale, Endian.little);
    d.setUint8(offset + 20, ccd ? 1 : 0);
  }

