  static RigidBody decode(ByteData d, int offset, Uint8List tail) {
    return RigidBody(
      bodyType: enumValue(BodyType.values, d.getUint32(offset + 0, Endian.little), 'fynkel.BodyType'),
      mass: d.getFloat32(offset + 4, Endian.little),
      linearDamping: d.getFloat32(offset + 8, Endian.little),
      angularDamping: d.getFloat32(offset + 12, Endian.little),
      gravityScale: d.getFloat32(offset + 16, Endian.little),
      ccd: d.getUint8(offset + 20) != 0,
    );
  }

  /// This value with the given fields replaced.
  RigidBody copyWith({
    BodyType? bodyType,
    double? mass,
    double? linearDamping,
    double? angularDamping,
    double? gravityScale,
    bool? ccd,
  }) =>
      RigidBody(
        bodyType: bodyType ?? this.bodyType,
        mass: mass ?? this.mass,
        linearDamping: linearDamping ?? this.linearDamping,
        angularDamping: angularDamping ?? this.angularDamping,
        gravityScale: gravityScale ?? this.gravityScale,
        ccd: ccd ?? this.ccd,
      );

  @override
  bool operator ==(Object other) =>
