  @override
  int get hashCode => Object.hashAll([bodyType, mass, linearDamping, angularDamping, gravityScale, ccd]);

  @override
  String toString() => 'RigidBody(bodyType: $bodyType, mass: $mass, linearDamping: $linearDamping, angularDamping: $angularDamping, gravityScale: $gravityScale, ccd: $ccd)';
}

/// A collision shape on the entity, in the entity's local frame scaled by the entity's world scale. Alone it is static geometry; with a `RigidBody` it is that body's shape.
///
/// `fynkel.Collider` (component, id 11, 72 bytes).
class Collider implements WireRecord {
  const Collider({
    required this.shape,
    required this.size,
    this.mesh,
    required this.offset,
    required this.friction,
    required this.restitution,
    required this.isSensor,
    required this.layer,
    required this.mask,
  });

  final ColliderShape shape;
  /// Metres; what each component means depends on `shape`.
  final Vec3 size;
  /// The mesh sub-asset for `shape: mesh` (`mesh/<n>` of an imported glTF), ignored otherwise.
  final AssetRef? mesh;
  /// Local translation of the shape from the entity's origin, metres.
  final Vec3 offset;
  /// Coulomb friction coefficient, `>= 0` (0.5 is rubber on concrete).
  final double friction;
  /// Bounciness `0..=1`.
  final double restitution;
  /// A sensor reports trigger events and applies no forces.
  final bool isSensor;
  /// Membership bits (bit `i` = layer `i` of the project's `physics.layers`); default layer 0.
  final int layer;
  /// Which layers this collider collides with (both sides must agree).
  final int mask;

  static const String schemaName = 'fynkel.Collider';
  static const int wireSize = 72;
  static const int componentId = 11;

  /// Writes [wireSize] bytes at [offset]; strings go to [strings].
  @override
  void encode(ByteData d, int offset, WireStrings strings) {
    d.setUint32(offset + 0, shape.index, Endian.little);
    writeVec3(d, offset + 4, size);
    writeOptionalAssetRef(d, offset + 16, mesh, strings);
    writeVec3(d, offset + 40, this.offset);
    d.setFloat32(offset + 52, friction, Endian.little);
    d.setFloat32(offset + 56, restitution, Endian.little);
    d.setUint8(offset + 60, isSensor ? 1 : 0);
    d.setUint32(offset + 64, layer, Endian.little);
    d.setUint32(offset + 68, mask, Endian.little);
  }

  /// Reads [wireSize] bytes at [offset]; [tail] resolves strings.
  static Collider decode(ByteData d, int offset, Uint8List tail) {
    return Collider(
      shape: enumValue(ColliderShape.values, d.getUint32(offset + 0, Endian.little), 'fynkel.ColliderShape'),
      size: readVec3(d, offset + 4),
      mesh: readOptionalAssetRef(d, offset + 16, tail),
      offset: readVec3(d, offset + 40),
      friction: d.getFloat32(offset + 52, Endian.little),
      restitution: d.getFloat32(offset + 56, Endian.little),
      isSensor: d.getUint8(offset + 60) != 0,
      layer: d.getUint32(offset + 64, Endian.little),
      mask: d.getUint32(offset + 68, Endian.little),
    );
  }

  /// This value with the given fields replaced.
  Collider copyWith({
    ColliderShape? shape,
    Vec3? size,
    AssetRef? mesh,
    Vec3? offset,
    double? friction,
    double? restitution,
    bool? isSensor,
    int? layer,
    int? mask,
  }) =>
      Collider(
        shape: shape ?? this.shape,
        size: size ?? this.size,
        mesh: mesh ?? this.mesh,
        offset: offset ?? this.offset,
        friction: friction ?? this.friction,
        restitution: restitution ?? this.restitution,
        isSensor: isSensor ?? this.isSensor,
        layer: layer ?? this.layer,
        mask: mask ?? this.mask,
      );

  @override
  bool operator ==(Object other) =>
      other is Collider && other.shape == shape && other.size == size && other.mesh == mesh && other.offset == offset && other.friction == friction && other.restitution == restitution && other.isSensor == isSensor && other.layer == layer && other.mask == mask;

  @override
  int get hashCode => Object.hashAll([shape, size, mesh, offset, friction, restitution, isSensor, layer, mask]);

  @override
  String toString() => 'Collider(shape: $shape, size: $size, mesh: $mesh, offset: $offset, friction: $friction, restitution: $restitution, isSensor: $isSensor, layer: $layer, mask: $mask)';
}

