/// One spatial query in a `PhysicsQueries` buffer (`fynkel_world_physics_query`); answered by `fynkel.rec.PhysicsHit` records carrying its `id`. Colliders are candidates when their `layer` shares a bit with `mask`; the `exclude` entity's colliders are skipped; sensors are hit only with `hit_sensors`.
///
/// `fynkel.rec.PhysicsQuery` (record, id 0, 88 bytes).
class PhysicsQueryRecord implements WireRecord {
  const PhysicsQueryRecord({
    required this.id,
    required this.kind,
    required this.shape,
    required this.size,
    required this.origin,
    required this.rotation,
    required this.direction,
    required this.maxDistance,
    required this.mask,
    this.exclude,
    required this.maxHits,
    required this.hitSensors,
  });

  /// Echoed by every hit of this query.
  final int id;
  final PhysicsQueryKind kind;
  /// `shapeCast`/`overlap`: `box`, `sphere` or `capsule` (never `mesh`) with `size` as `fynkel.Collider` defines it.
  final ColliderShape shape;
  final Vec3 size;
  final Vec3 origin;
  /// The shape's orientation.
  final Quat rotation;
  /// `raycast`/`shapeCast`; need not be normalised.
  final Vec3 direction;
  final double maxDistance;
  final int mask;
  final int? exclude;
  /// `raycast`/`overlap`: at most this many hits, nearest first (0 = 1).
  final int maxHits;
  final bool hitSensors;

  static const String schemaName = 'fynkel.rec.PhysicsQuery';
  static const int wireSize = 88;

  /// Writes [wireSize] bytes at [offset]; strings go to [strings].
  @override
  void encode(ByteData d, int offset, WireStrings strings) {
    d.setUint32(offset + 0, id, Endian.little);
    d.setUint32(offset + 4, kind.index, Endian.little);
    d.setUint32(offset + 8, shape.index, Endian.little);
    writeVec3(d, offset + 12, size);
    writeVec3(d, offset + 24, origin);
    writeQuat(d, offset + 36, rotation);
    writeVec3(d, offset + 52, direction);
    d.setFloat32(offset + 64, maxDistance, Endian.little);
    d.setUint32(offset + 68, mask, Endian.little);
    d.setUint64(offset + 72, exclude ?? 0, Endian.little);
    d.setUint32(offset + 80, maxHits, Endian.little);
    d.setUint8(offset + 84, hitSensors ? 1 : 0);
  }

  /// Reads [wireSize] bytes at [offset]; [tail] resolves strings.
  static PhysicsQueryRecord decode(ByteData d, int offset, Uint8List tail) {
    return PhysicsQueryRecord(
      id: d.getUint32(offset + 0, Endian.little),
      kind: enumValue(PhysicsQueryKind.values, d.getUint32(offset + 4, Endian.little), 'fynkel.PhysicsQueryKind'),
      shape: enumValue(ColliderShape.values, d.getUint32(offset + 8, Endian.little), 'fynkel.ColliderShape'),
      size: readVec3(d, offset + 12),
      origin: readVec3(d, offset + 24),
      rotation: readQuat(d, offset + 36),
      direction: readVec3(d, offset + 52),
      maxDistance: d.getFloat32(offset + 64, Endian.little),
      mask: d.getUint32(offset + 68, Endian.little),
      exclude: optionalEntity(d.getUint64(offset + 72, Endian.little)),
      maxHits: d.getUint32(offset + 80, Endian.little),
      hitSensors: d.getUint8(offset + 84) != 0,
    );
  }

  @override
  bool operator ==(Object other) =>
      other is PhysicsQueryRecord && other.id == id && other.kind == kind && other.shape == shape && other.size == size && other.origin == origin && other.rotation == rotation && other.direction == direction && other.maxDistance == maxDistance && other.mask == mask && other.exclude == exclude && other.maxHits == maxHits && other.hitSensors == hitSensors;

  @override
  int get hashCode => Object.hashAll([id, kind, shape, size, origin, rotation, direction, maxDistance, mask, exclude, maxHits, hitSensors]);

  @override
  String toString() => 'PhysicsQueryRecord(id: $id, kind: $kind, shape: $shape, size: $size, origin: $origin, rotation: $rotation, direction: $direction, maxDistance: $maxDistance, mask: $mask, exclude: $exclude, maxHits: $maxHits, hitSensors: $hitSensors)';
}

