  final double seconds;

  static const String schemaName = 'fynkel.LifetimeDespawn';
  static const int wireSize = 8;
  static const int componentId = 18;

  /// Writes [wireSize] bytes at [offset]; strings go to [strings].
  @override
  void encode(ByteData d, int offset, WireStrings strings) {
    d.setFloat32(offset + 0, seconds, Endian.little);
  }

  /// Reads [wireSize] bytes at [offset]; [tail] resolves strings.
  static LifetimeDespawn decode(ByteData d, int offset, Uint8List tail) {
    return LifetimeDespawn(
      seconds: d.getFloat32(offset + 0, Endian.little),
    );
  }

  /// This value with the given fields replaced.
  LifetimeDespawn copyWith({
    double? seconds,
  }) =>
      LifetimeDespawn(
