/// Instantiates `prefab` at the entity's world pose `rate` times per second (pre-tick slot; the fractional remainder carries over so 2.5/s alternates 2 and 3 per second): each instance is an unparented anchor named after the prefab whose children are the prefab's roots — exactly `World::instantiate` — with a `LifetimeDespawn { seconds: lifetime }` when `lifetime > 0`, and every dynamic `RigidBody` in it starts at `velocity` (world axes). With `max_alive > 0` no more are spawned while that many of this emitter's instances live. The world must know the prefab (`World::register_prefab`; the loaders register every prefab a loaded scene's emitters name, `PREFAB_UNAVAILABLE` once otherwise).
///
/// `fynkel.Emitter` (component, id 19, 56 bytes).
class Emitter implements WireRecord {
  const Emitter({
    required this.prefab,
    required this.rate,
    required this.lifetime,
    required this.maxAlive,
    required this.velocity,
    required this.enabled,
  });

  /// The `.prefab.json` asset to instantiate.
  final AssetRef prefab;
  /// Instances per second, `>= 0`; `0` pauses.
  final double rate;
  /// Seconds each instance lives, `>= 0`; `0` keeps them.
  final double lifetime;
  /// Ceiling on this emitter's live instances; `0` is unlimited.
  final int maxAlive;
  /// Initial linear velocity of each instance's dynamic bodies, m/s.
  final Vec3 velocity;
  final bool enabled;

  static const String schemaName = 'fynkel.Emitter';
  static const int wireSize = 56;
  static const int componentId = 19;

  /// Writes [wireSize] bytes at [offset]; strings go to [strings].
  @override
  void encode(ByteData d, int offset, WireStrings strings) {
    writeAssetRef(d, offset + 0, prefab, strings);
    d.setFloat32(offset + 24, rate, Endian.little);
    d.setFloat32(offset + 28, lifetime, Endian.little);
    d.setUint32(offset + 32, maxAlive, Endian.little);
    writeVec3(d, offset + 36, velocity);
    d.setUint8(offset + 48, enabled ? 1 : 0);
  }

  /// Reads [wireSize] bytes at [offset]; [tail] resolves strings.
  static Emitter decode(ByteData d, int offset, Uint8List tail) {
    return Emitter(
      prefab: readAssetRef(d, offset + 0, tail),
      rate: d.getFloat32(offset + 24, Endian.little),
      lifetime: d.getFloat32(offset + 28, Endian.little),
      maxAlive: d.getUint32(offset + 32, Endian.little),
      velocity: readVec3(d, offset + 36),
      enabled: d.getUint8(offset + 48) != 0,
    );
  }

  /// This value with the given fields replaced.
  Emitter copyWith({
    AssetRef? prefab,
    double? rate,
    double? lifetime,
    int? maxAlive,
    Vec3? velocity,
    bool? enabled,
  }) =>
      Emitter(
        prefab: prefab ?? this.prefab,
        rate: rate ?? this.rate,
        lifetime: lifetime ?? this.lifetime,
        maxAlive: maxAlive ?? this.maxAlive,
        velocity: velocity ?? this.velocity,
        enabled: enabled ?? this.enabled,
      );

  @override
  bool operator ==(Object other) =>
      other is Emitter && other.prefab == prefab && other.rate == rate && other.lifetime == lifetime && other.maxAlive == maxAlive && other.velocity == velocity && other.enabled == enabled;

  @override
  int get hashCode => Object.hashAll([prefab, rate, lifetime, maxAlive, velocity, enabled]);

  @override
  String toString() => 'Emitter(prefab: $prefab, rate: $rate, lifetime: $lifetime, maxAlive: $maxAlive, velocity: $velocity, enabled: $enabled)';
}

/// `FYNKEL_QUERY_SYSTEMS` (M3-10): one per [`SystemKind`], the last step's wall time and the number of things that phase touched. What the HUD and the headless report print as per-system time.
///
/// `fynkel.rec.SystemTime` (record, id 0, 16 bytes).
class SystemTimeRecord implements WireRecord {
  const SystemTimeRecord({
    required this.system,
    required this.entities,
    required this.micros,
  });

  final SystemKind system;
  final int entities;
  /// Microseconds of wall time in the last step.
  final int micros;

  static const String schemaName = 'fynkel.rec.SystemTime';
  static const int wireSize = 16;

  /// Writes [wireSize] bytes at [offset]; strings go to [strings].
  @override
  void encode(ByteData d, int offset, WireStrings strings) {
    d.setUint32(offset + 0, system.index, Endian.little);
    d.setUint32(offset + 4, entities, Endian.little);
    d.setUint32(offset + 8, micros, Endian.little);
  }

  /// Reads [wireSize] bytes at [offset]; [tail] resolves strings.
  static SystemTimeRecord decode(ByteData d, int offset, Uint8List tail) {
    return SystemTimeRecord(
      system: enumValue(SystemKind.values, d.getUint32(offset + 0, Endian.little), 'fynkel.SystemKind'),
      entities: d.getUint32(offset + 4, Endian.little),
      micros: d.getUint32(offset + 8, Endian.little),
    );
  }

  @override
  bool operator ==(Object other) =>
      other is SystemTimeRecord && other.system == system && other.entities == entities && other.micros == micros;

  @override
