/// Names the event Dart hears when a collider enters or leaves this entity's **sensor** `Collider` (M3-12; `docs/scenes.md`): every physics `TriggerEnter`/`TriggerExit` the entity takes part in also produces a general-lane `ZoneEntered`/`ZoneExited` event carrying `event`, the zone entity and the other one, so gameplay subscribes by name (`world.zones.on('collect', …)`) instead of matching colliders. With `once` the component is removed right after the first entry (no exit follows; the collider stays until the entity goes). An entity without a sensor collider never fires (`fynkel validate`: `FYN-H0009`).
///
/// `fynkel.TriggerZone` (component, id 20, 16 bytes).
class TriggerZone implements WireRecord {
  const TriggerZone({
    required this.event,
    required this.once,
  });

  /// The event name, non-empty.
  final String event;
  /// Fire on the first entry only, then drop the component.
  final bool once;

  static const String schemaName = 'fynkel.TriggerZone';
  static const int wireSize = 16;
  static const int componentId = 20;

  /// Writes [wireSize] bytes at [offset]; strings go to [strings].
  @override
  void encode(ByteData d, int offset, WireStrings strings) {
    writeWireString(d, offset + 0, event, strings);
    d.setUint8(offset + 8, once ? 1 : 0);
  }

  /// Reads [wireSize] bytes at [offset]; [tail] resolves strings.
  static TriggerZone decode(ByteData d, int offset, Uint8List tail) {
    return TriggerZone(
      event: readWireString(d, offset + 0, tail),
      once: d.getUint8(offset + 8) != 0,
    );
  }

  /// This value with the given fields replaced.
  TriggerZone copyWith({
    String? event,
    bool? once,
  }) =>
      TriggerZone(
        event: event ?? this.event,
        once: once ?? this.once,
      );

  @override
  bool operator ==(Object other) =>
      other is TriggerZone && other.event == event && other.once == once;

  @override
  int get hashCode => Object.hashAll([event, once]);

  @override
  String toString() => 'TriggerZone(event: $event, once: $once)';
}

/// A scene was unloaded (M3-12): its still-alive entities were destroyed (their `Destroyed` events precede this one) and the host released its asset residency.
///
