/// A `fynkel.TriggerZone` fired (M3-12): the body of `ZONE_ENTERED` (7) and `ZONE_EXITED` (8), on the general lane the tick the sensor saw it.
///
/// `fynkel.ev.Zone` (event, id 7, 24 bytes).
class ZoneEvent implements WireRecord {
  const ZoneEvent({
    required this.zone,
    required this.other,
    required this.event,
  });

  /// The entity carrying the `TriggerZone`.
  final int zone;
  /// The collider that entered or left.
  final int other;
  /// The zone's `event` name.
  final String event;

  static const String schemaName = 'fynkel.ev.Zone';
  static const int wireSize = 24;
  static const int eventKind = 7;

  /// Writes [wireSize] bytes at [offset]; strings go to [strings].
  @override
  void encode(ByteData d, int offset, WireStrings strings) {
    d.setUint64(offset + 0, zone, Endian.little);
    d.setUint64(offset + 8, other, Endian.little);
    writeWireString(d, offset + 16, event, strings);
  }

  /// Reads [wireSize] bytes at [offset]; [tail] resolves strings.
  static ZoneEvent decode(ByteData d, int offset, Uint8List tail) {
    return ZoneEvent(
      zone: d.getUint64(offset + 0, Endian.little),
      other: d.getUint64(offset + 8, Endian.little),
      event: readWireString(d, offset + 16, tail),
    );
  }

  @override
  // ignore: avoid_renaming_method_parameters
  bool operator ==(Object that) =>
      that is ZoneEvent && that.zone == zone && that.other == other && that.event == event;

  @override
  int get hashCode => Object.hashAll([zone, other, event]);

  @override
  String toString() => 'ZoneEvent(zone: $zone, other: $other, event: $event)';
}

/// `fynkel.Settings` (record, id 0, 24 bytes).
class Settings implements WireRecord {
  const Settings({
    required this.masterVolume,
    required this.musicVolume,
    required this.sfxVolume,
    required this.muted,
    required this.quality,
  });

  /// Gain of the `master` bus, `0..=1`.
  final double masterVolume;
  /// Gain of the `music` bus, `0..=1`.
  final double musicVolume;
  /// Gain of the `sfx` bus, `0..=1`.
  final double sfxVolume;
  /// Every bus silent; the volumes are kept.
  final bool muted;
  /// A quality profile name from the project file; empty means the project's default profile.
  final String quality;

  static const String schemaName = 'fynkel.Settings';
  static const int wireSize = 24;

  /// Writes [wireSize] bytes at [offset]; strings go to [strings].
  @override
  void encode(ByteData d, int offset, WireStrings strings) {
    d.setFloat32(offset + 0, masterVolume, Endian.little);
    d.setFloat32(offset + 4, musicVolume, Endian.little);
    d.setFloat32(offset + 8, sfxVolume, Endian.little);
    d.setUint8(offset + 12, muted ? 1 : 0);
    writeWireString(d, offset + 16, quality, strings);
  }

  /// Reads [wireSize] bytes at [offset]; [tail] resolves strings.
  static Settings decode(ByteData d, int offset, Uint8List tail) {
    return Settings(
      masterVolume: d.getFloat32(offset + 0, Endian.little),
      musicVolume: d.getFloat32(offset + 4, Endian.little),
      sfxVolume: d.getFloat32(offset + 8, Endian.little),
      muted: d.getUint8(offset + 12) != 0,
      quality: readWireString(d, offset + 16, tail),
    );
  }

  @override
  bool operator ==(Object other) =>
      other is Settings && other.masterVolume == masterVolume && other.musicVolume == musicVolume && other.sfxVolume == sfxVolume && other.muted == muted && other.quality == quality;

  @override
  int get hashCode => Object.hashAll([masterVolume, musicVolume, sfxVolume, muted, quality]);

  @override
  String toString() => 'Settings(masterVolume: $masterVolume, musicVolume: $musicVolume, sfxVolume: $sfxVolume, muted: $muted, quality: $quality)';
}

/// How the world reads one native component off the wire.
class ComponentCodec {
  const ComponentCodec(this.id, this.name, this.type, this.wireSize, this.decode);

  /// `ComponentId`.
  final int id;
  final String name;
  final Type type;
  final int wireSize;
  final WireRecord Function(ByteData d, int offset, Uint8List tail) decode;
}

